import { spawnSync } from 'node:child_process'
import assert from 'node:assert/strict'
import { test } from 'node:test'
import { fileURLToPath } from 'node:url'

const cli = fileURLToPath(new URL('../src/cli.js', import.meta.url))

function run(argv, stdin = '') {
  const result = spawnSync(process.execPath, [cli, ...argv], { encoding: 'utf8', input: stdin })
  return { code: result.status, out: result.stdout, err: result.stderr }
}

test('a scalar assignment becomes one JSON member', () => {
  assert.deepEqual(run(['json'], 'a = 1
'), { code: 0, out: '{
  "a": 1
}
', err: '' })
})

test('members print in ascending key order', () => {
  assert.equal(run(['json'], 'b = 1
a = 2
').out, '{
  "a": 2,
  "b": 1
}
')
})

test('a basic string decodes its escapes', () => {
  assert.equal(run(['json'], 'a = "x\ty"
').out, '{
  "a": "x\ty"
}
')
})

test('a literal string keeps its backslashes', () => {
  assert.equal(run(['json'], "a = 'x\ty'
").out, '{
  "a": "x\\ty"
}
')
})

test('booleans are booleans', () => {
  assert.equal(run(['json'], 'a = true
b = false
').out, '{
  "a": true,
  "b": false
}
')
})

test('an integer may carry underscore separators', () => {
  assert.equal(run(['json'], 'a = 1_000
').out, '{
  "a": 1000
}
')
})

test('an array holds its items in order', () => {
  assert.equal(run(['json'], 'a = [1, 2]
').out, '{
  "a": [
    1,
    2
  ]
}
')
})

test('a table header nests the keys under it', () => {
  assert.equal(run(['json'], '[s]
a = 1
').out, '{
  "s": {
    "a": 1
  }
}
')
})

test('a dotted header nests two levels', () => {
  assert.equal(run(['json'], '[s.t]
a = 1
').out, '{
  "s": {
    "t": {
      "a": 1
    }
  }
}
')
})

test('a doubled header appends to an array of tables', () => {
  assert.equal(run(['json'], '[[i]]
a = 1
[[i]]
a = 2
').out, '{
  "i": [
    {
      "a": 1
    },
    {
      "a": 2
    }
  ]
}
')
})

test('comments and blank lines are ignored', () => {
  assert.equal(run(['json'], '# note

a = 1 # tail
').out, '{
  "a": 1
}
')
})

test('an empty document is an empty object', () => {
  assert.deepEqual(run(['json'], ''), { code: 0, out: '{}
', err: '' })
})

test('keys list every path with its type', () => {
  assert.equal(run(['keys'], '[s]
a = 1
b = "x"
').out, 's table
s.a integer
s.b string
')
})

test('keys tell an integer from a float', () => {
  assert.equal(run(['keys'], 'a = 1
b = 1.5
').out, 'a integer
b float
')
})

test('a key defined twice is rejected', () => {
  const result = run(['json'], 'a = 1
a = 2
')
  assert.equal(result.code, 2)
  assert.equal(result.out, '')
  assert.equal(result.err, 'error: line 2: key a is defined twice
')
})

test('a table header used twice is rejected', () => {
  assert.equal(run(['json'], '[s]
[s]
').err, 'error: line 2: table s is defined twice
')
})

test('a value that parses as nothing is rejected', () => {

#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

process.stderr.write('error: not implemented\n')
process.exit(1)
test('a value that parses as nothing is rejected', () => {
  assert.equal(run(['json'], 'a = nope\n').err, 'error: line 1: invalid value nope\n')
})

test('an unknown mode is rejected', () => {
  const result = run(['toml'], '')
  assert.equal(result.code, 2)
  assert.equal(result.err, 'error: usage: cli.js json|keys\n')
})

